from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.casefold()
        match_value = match_value.casefold()

        if match_value.startswith("*."):
            domain = match_value[2:]
            # The domain itself does not match; only strict subdomains do.
            return host.endswith("." + domain) and host != domain

        return host == match_value

    def replace_host(parts, new_host):
        netloc = parts.netloc

        # Preserve userinfo, if present.
        userinfo = ""
        if "@" in netloc:
            userinfo, netloc = netloc.rsplit("@", 1)
            userinfo += "@"

        # Preserve the original port text.
        port_suffix = ""
        if netloc.startswith("["):  # IPv6 literal
            closing = netloc.find("]")
            if closing != -1:
                port_suffix = netloc[closing + 1:]
        elif ":" in netloc:
            _, possible_port = netloc.rsplit(":", 1)
            if possible_port.isdigit():
                port_suffix = ":" + possible_port

        # Bracket an IPv6 replacement host when necessary.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = userinfo + new_host + port_suffix
        return urlunsplit((
            parts.scheme,
            new_netloc,
            parts.path,
            parts.query,
            parts.fragment,
        ))

    results = []

    for url in urls:
        parts = urlsplit(url)
        rewritten_url = url

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            matched = False

            if match_type == "path_prefix":
                matched = parts.path.startswith(match_value)

            elif match_type == "host":
                matched = host_matches(parts.hostname, match_value)

            elif match_type == "query_param":
                parameter_names = {
                    name for name, _ in parse_qsl(
                        parts.query,
                        keep_blank_values=True
                    )
                }
                matched = match_value in parameter_names

            if not matched:
                continue

            if action == "block":
                rewritten_url = None

            elif action == "strip_prefix":
                prefix = rule["action_value"]
                path = parts.path

                if path.startswith(prefix):
                    path = path[len(prefix):]

                if path == "":
                    path = "/"

                rewritten_url = urlunsplit((
                    parts.scheme,
                    parts.netloc,
                    path,
                    parts.query,
                    parts.fragment,
                ))

            elif action == "redirect_host":
                rewritten_url = replace_host(
                    parts,
                    rule["action_value"]
                )

            elif action == "add_query_param":
                addition = rule["action_value"]
                query = (
                    f"{parts.query}&{addition}"
                    if parts.query
                    else addition
                )

                rewritten_url = urlunsplit((
                    parts.scheme,
                    parts.netloc,
                    parts.path,
                    query,
                    parts.fragment,
                ))

            # Only the first matching rule is applied.
            break

        results.append(rewritten_url)

    return results
